#![no_std]
use soroban_sdk::{
    contract, contracterror, contractimpl, contracttype, panic_with_error, token, Address, Env,
};

// Ledger counts: roughly 30 and 60 days on Stellar's ~5-second ledgers.
const LIFETIME_THRESHOLD: u32 = 17_280 * 30;
const LIFETIME_BUMP: u32 = 17_280 * 60;

#[contracttype]
#[derive(Clone)]
pub enum DataKey {
    /// Address of the staked token (the native XLM Stellar Asset Contract for this deployment).
    Token,
    /// Sum of every user's stake.
    Total,
    /// One user's stake.
    Staked(Address),
}

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
#[repr(u32)]
pub enum Error {
    /// The amount must be greater than zero.
    InvalidAmount = 1,
    /// The user tries to unstake more than they have staked.
    InsufficientStake = 2,
}

#[contract]
pub struct Staking;

#[contractimpl]
impl Staking {
    /// Runs once at deploy time, so the contract is ready to use as soon as it exists.
    pub fn __constructor(env: Env, token: Address) {
        env.storage().instance().set(&DataKey::Token, &token);
        env.storage().instance().set(&DataKey::Total, &0_i128);
        env.storage()
            .instance()
            .extend_ttl(LIFETIME_THRESHOLD, LIFETIME_BUMP);
    }

    /// Transfers `amount` of the token from `user` to this contract and credits the stake.
    pub fn stake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }

        token::Client::new(&env, &Self::token(&env)).transfer(
            &user,
            &env.current_contract_address(),
            &amount,
        );

        let key = DataKey::Staked(user);
        let staked: i128 = env.storage().persistent().get(&key).unwrap_or(0);
        Self::write_stake(&env, &key, staked + amount);
        Self::write_total(&env, Self::total_staked(env.clone()) + amount);
    }

    /// Debits `amount` from the user's stake and transfers it back to `user`.
    pub fn unstake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }

        let key = DataKey::Staked(user.clone());
        let staked: i128 = env.storage().persistent().get(&key).unwrap_or(0);
        if staked < amount {
            panic_with_error!(&env, Error::InsufficientStake);
        }

        // Update the books before transferring out.
        Self::write_stake(&env, &key, staked - amount);
        Self::write_total(&env, Self::total_staked(env.clone()) - amount);

        token::Client::new(&env, &Self::token(&env)).transfer(
            &env.current_contract_address(),
            &user,
            &amount,
        );
    }

    /// The amount `user` has staked.
    pub fn staked(env: Env, user: Address) -> i128 {
        env.storage()
            .persistent()
            .get(&DataKey::Staked(user))
            .unwrap_or(0)
    }

    /// The amount staked by everyone.
    pub fn total_staked(env: Env) -> i128 {
        env.storage().instance().get(&DataKey::Total).unwrap_or(0)
    }

    /// The token this contract stakes.
    pub fn token(env: &Env) -> Address {
        env.storage().instance().get(&DataKey::Token).unwrap()
    }

    fn write_stake(env: &Env, key: &DataKey, amount: i128) {
        env.storage().persistent().set(key, &amount);
        env.storage()
            .persistent()
            .extend_ttl(key, LIFETIME_THRESHOLD, LIFETIME_BUMP);
    }

    fn write_total(env: &Env, amount: i128) {
        env.storage().instance().set(&DataKey::Total, &amount);
        env.storage()
            .instance()
            .extend_ttl(LIFETIME_THRESHOLD, LIFETIME_BUMP);
    }
}

