import { connection } from "next/server";
import { Suspense } from "react";
import { stakingContract } from "@/lib/contracts";
import { stellar } from "@/lib/stellar";

type SearchParams = Promise<{ address?: string | string[] }>;

function errorText(error: unknown): string {
  // Some network errors arrive with an empty message; fall back to their text.
  const reason = (error instanceof Error && error.message) || String(error) || "unknown error";
  return `${reason} (RPC: ${stellar.rpcUrl ?? "not set"})`;
}

async function TotalStaked() {
  // Read the contract when a request arrives, not while `next build` prerenders the page.
  await connection();
  try {
    const { result } = await stakingContract().total_staked();
    return (
      <p>
        Total staked: <span data-testid="total-staked">{result.toString()}</span>
      </p>
    );
  } catch (error) {
    return <p data-testid="total-staked-error">Could not read total staked: {errorText(error)}</p>;
  }
}

async function StakedBy({ searchParams }: { searchParams: SearchParams }) {
  const { address } = await searchParams;
  if (!address || Array.isArray(address)) {
    return <p>Add <code>?address=G…</code> to the URL to see one address&apos;s stake.</p>;
  }
  try {
    const { result } = await stakingContract().staked({ user: address });
    return (
      <p>
        Staked by <code>{address}</code>:{" "}
        <span data-testid="staked-amount">{result.toString()}</span>
      </p>
    );
  } catch (error) {
    return <p data-testid="staked-error">Could not read the stake for {address}: {errorText(error)}</p>;
  }
}

export default function StakingPage({ searchParams }: { searchParams: SearchParams }) {
  return (
    <main>
      <h1>Staking</h1>
      <p>
        Network: <code>{stellar.network}</code>
      </p>
      <Suspense fallback={<p>Reading the total…</p>}>
        <TotalStaked />
      </Suspense>
      <Suspense fallback={<p>Reading the stake…</p>}>
        <StakedBy searchParams={searchParams} />
      </Suspense>
    </main>
  );
}
