type Outcome = { value: string } | { error: string };

function errorText(error: unknown): string {
  // Some network errors arrive with an empty message; fall back to their text.
  const reason = (error instanceof Error && error.message) || String(error) || "unknown error";
  return `${reason} (RPC: ${stellar.rpcUrl ?? "not set"})`;
}

async function readTotal(): Promise<Outcome> {
  try {
    const { result } = await stakingContract().total_staked();
    return { value: result.toString() };
  } catch (error) {
    return { error: errorText(error) };
  }
}

async function readStaked(address: string): Promise<Outcome> {
  try {
    const { result } = await stakingContract().staked({ user: address });
    return { value: result.toString() };
  } catch (error) {
    return { error: errorText(error) };
  }
}

async function TotalStaked() {
  // Read the contract when a request arrives, not while `next build` prerenders the page.
  await connection();
  const outcome = await readTotal();
  if ("error" in outcome) {
    return <p data-testid="total-staked-error">Could not read total staked: {outcome.error}</p>;
  }
  return (
    <p>
      Total staked: <span data-testid="total-staked">{outcome.value}</span>
    </p>
  );
}

async function StakedBy({ searchParams }: { searchParams: SearchParams }) {
  const { address } = await searchParams;
  if (!address || Array.isArray(address)) {
    return (
      <p>
        Add <code>?address=G…</code> to the URL to see one address&apos;s stake.
      </p>
    );
  }
  const outcome = await readStaked(address);
  if ("error" in outcome) {
    return (
      <p data-testid="staked-error">
        Could not read the stake for {address}: {outcome.error}
      </p>
    );
  }
  return (
    <p>
      Staked by <code>{address}</code>: <span data-testid="staked-amount">{outcome.value}</span>
    </p>
  );
}

export default function StakingPage({ searchParams }: { searchParams: SearchParams }) {
  return (
    <main>
      <h1>Staking</h1>
      <p>
        Network: <code>{stellar.network}</code>
      </p>
      <Suspense fallback={<p>Reading the total…</p>}>
        <TotalStaked />
      </Suspense>
      <Suspense fallback={<p>Reading the stake…</p>}>
        <StakedBy searchParams={searchParams} />
      </Suspense>
    </main>
  );
}
